			["Ahri"] = new ChampionDef("Ahri", "the Nine-Tailed Fox", "Innately connected to the magic of the spirit realm, Ahri is a fox-like vastaya who can manipulate her prey's emotions and consume their essence—receiving flashes of their memory and insight from each soul she consumes. Once a powerful yet wayward predator, Ahri is now traveling the world in search of remnants of her ancestors while also trying to replace her stolen memories with ones of her own making.", 1, 1, new SpellDef[] { new SpellDef("P", "Essence Theft", "After killing 9 minions or monsters, Ahri heals. After taking down an enemy champion, Ahri heals for a greater amount.", 0, 0, 0, 0, 0, 0, 0), new SpellDef("Q", "Orb of Deception", "Ahri throws then pulls back her orb, dealing ? magic damage on the way out and ? true damage on the way back.?", 3.5f, 27, 970, 0, 0, 0, 1), new SpellDef("W", "Fox-Fire", "Ahri releases 3 fox-fires that seek nearby enemies and deal ? magic damage, reduced to ? damage beyond the first. She also gains ?% Move Speed decaying over ? seconds.?", 4.5f, 15, 700, 3, 0, 0, 1), new SpellDef("E", "Charm", "Ahri blows a kiss that Charms the first enemy hit for ? seconds and deals ? magic damage.?", 6.0f, 30, 975, 0, 4, 0, 1), new SpellDef("R", "Spirit Rush", "Ahri nimbly dashes, firing ? essence bolts at nearby enemies, prioritizing champions. These bolts deal ? magic damage each. Spirit Rush can be Recast up to 2 more times within ? seconds. Consuming a champion's Essence with Essence Theft during this period extends the recast window by up to ? seconds and grants an additional recast of Spirit Rush (up to ? stored).?", 60.0f, 50, 450, 1, 0, 0, 1) }),
